import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.zaPC62Fc.js";const u=JSON.parse('{"title":"Asset workflow: ChatGPT paints, Claude finishes","description":"","frontmatter":{},"headers":[],"relativePath":"guide/asset-workflow.md","filePath":"guide/asset-workflow.md"}'),r={name:"guide/asset-workflow.md"};function i(n,e,l,h,c,d){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="asset-workflow-chatgpt-paints-claude-finishes" tabindex="-1">Asset workflow: ChatGPT paints, Claude finishes <a class="header-anchor" href="#asset-workflow-chatgpt-paints-claude-finishes" aria-label="Permalink to &quot;Asset workflow: ChatGPT paints, Claude finishes&quot;">​</a></h1><p>Claude can draw simple shapes in code, but what it draws by itself is often not pretty enough, and &quot;painting&quot; with code costs a lot of tokens. So the work is split:</p><table tabindex="0"><thead><tr><th>Who</th><th>Does</th><th>Why</th></tr></thead><tbody><tr><td><strong>ChatGPT</strong> (image generation)</td><td>The paintings: tank interiors, glass overlays, orbs, icons, text art</td><td>It makes polished 2D art cheaply</td></tr><tr><td><strong>Claude</strong></td><td>Checks the files, resizes, cuts the background, wires them into the game, animates them, adds particles and sound, tests the frame rate</td><td>Claude knows the code and can test in the running game</td></tr><tr><td><strong>People</strong></td><td>Choose the style, approve the results, commit and release</td><td>Art direction and publishing stay human</td></tr></tbody></table><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><strong>Write the asset list first.</strong> For each picture: name, size and proportions on screen, what is behind it and in front of it, the style reference (a screenshot of existing game art is the best reference), and whether it needs a transparent background.</li><li><strong>Generate in ChatGPT.</strong> Use one chat per asset set so the style stays consistent, and ask for the next piece in the same chat (&quot;matching front glass for this tank&quot;). Claude can drive the browser through the Claude in Chrome extension: it opens the chat tool in a new tab (you stay signed in), works only in the project you name, sends the prompts, and downloads only the pictures for this task.</li><li><strong>Hand over the raw files.</strong> They go to <code>Added Assets/&lt;set&gt;/</code> with plain names such as <code>target_back.png</code>, <code>target_front.png</code>. Keep the originals; the game uses resized copies.</li><li><strong>Claude checks and prepares.</strong> Alpha channel present, centre and corners as intended (a front glass must be transparent in the middle), proportions match the back picture. Then it resizes to about twice the on-screen size (so a phone at 3x is still sharp enough) and writes the copies to <code>public/ui/...</code>.</li><li><strong>Claude wires it in.</strong> Layer the pictures (back, fish, front), add a little motion (shimmer, bubbles, whirl, shake), and test on a phone-sized view with the <code>?fps=1</code> meter.</li><li><strong>Polish together.</strong> If a picture is off (colour, edge, scale), either ask ChatGPT for a new version in the same chat, or let Claude fix it in code (tint, crop, mask).</li></ol><h2 id="prompt-recipe" tabindex="-1">Prompt recipe <a class="header-anchor" href="#prompt-recipe" aria-label="Permalink to &quot;Prompt recipe&quot;">​</a></h2><p>State, in this order: the game and the use (&quot;game UI asset for a mobile casual puzzle game&quot;), the shape and proportions, the style (&quot;cute glossy cartoon, bold clean outlines, bright saturated colours&quot;), what to show, and the exclusions (&quot;NO frame, NO fish, NO text&quot;), then &quot;transparent PNG background&quot;. For pairs:</p><ul><li><strong>Back picture</strong>: &quot;Show only the INSIDE of the tank: water gradient, light rays, sandy floor, plants, bubbles. NO glass frame.&quot;</li><li><strong>Front picture</strong>: &quot;The matching FRONT GLASS overlay for the exact same tank, same size. Almost entirely transparent: only a thin glass rim, a diagonal light streak, a reflection line at the top. The centre stays fully transparent.&quot;</li><li>Make a second tank a <strong>different</strong> colour and trim (for example violet water and a gold trim) so the player never confuses the two.</li></ul><h2 id="checklist-before-a-picture-goes-into-the-game" tabindex="-1">Checklist before a picture goes into the game <a class="header-anchor" href="#checklist-before-a-picture-goes-into-the-game" aria-label="Permalink to &quot;Checklist before a picture goes into the game&quot;">​</a></h2><ul><li>Transparent PNG (alpha present, corners transparent).</li><li>Same proportions for each back and front pair.</li><li>No text baked into the picture.</li><li>Sharp at 2x the displayed size, but not much bigger (keep each file under about 500 KB).</li><li>The picture reads clearly at phone size (look at it small).</li></ul><h2 id="keep-the-public-repo-clean" tabindex="-1">Keep the public repo clean <a class="header-anchor" href="#keep-the-public-repo-clean" aria-label="Permalink to &quot;Keep the public repo clean&quot;">​</a></h2><p>The repository is public. Do not write links to chat tools, design tools, documents or drives, project or workspace names, e-mail addresses or personal paths in the docs, code comments or commit messages. Describe things in words instead.</p><ul><li><code>npm run check:public</code> scans everything that would be committed.</li><li><code>npm run hooks:install</code> adds a pre-commit hook that runs the same check on what is staged.</li><li>A release (<code>scripts/release.sh</code>) runs the check first and stops if it finds a problem.</li><li>A reviewed exception can carry the word <code>public-ok</code> on the same line.</li></ul>',13)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
